/**
 * Renders the generated token artefacts from palette.ts. Pure: returns file
 * contents, writes nothing. scripts/build-tokens.ts writes them, and the token
 * tests assert that the committed files match this output exactly.
 */
import { colors, shadowColor, type ColorName, type Role } from './palette';
import { parseHex } from './contrast';

const HEADER =
  '/* GENERATED by packages/ui/scripts/build-tokens.ts from src/tokens/palette.ts. Do not edit. */\n';

type Theme = 'light' | 'dark';

/** Utility prefix -> the role it needs, and the declarations it emits. */
export const UTILITIES: Record<string, { role: Role; css: (v: string) => string }> = {
  text: { role: 'text', css: (v) => `color: ${v};` },
  decoration: { role: 'text', css: (v) => `text-decoration-color: ${v};` },
  caret: { role: 'text', css: (v) => `caret-color: ${v};` },
  bg: { role: 'surface', css: (v) => `background-color: ${v};` },
  border: { role: 'line', css: (v) => `border-color: ${v};` },
  'border-x': { role: 'line', css: (v) => `border-inline-color: ${v};` },
  'border-y': { role: 'line', css: (v) => `border-block-color: ${v};` },
  'border-t': { role: 'line', css: (v) => `border-top-color: ${v};` },
  'border-r': { role: 'line', css: (v) => `border-right-color: ${v};` },
  'border-b': { role: 'line', css: (v) => `border-bottom-color: ${v};` },
  'border-l': { role: 'line', css: (v) => `border-left-color: ${v};` },
  'border-s': { role: 'line', css: (v) => `border-inline-start-color: ${v};` },
  'border-e': { role: 'line', css: (v) => `border-inline-end-color: ${v};` },
  divide: { role: 'line', css: (v) => `:where(& > :not(:last-child)) { border-color: ${v}; }` },
  outline: { role: 'line', css: (v) => `outline-color: ${v};` },
  ring: { role: 'line', css: (v) => `--tw-ring-color: ${v};` },
  'ring-offset': { role: 'line', css: (v) => `--tw-ring-offset-color: ${v};` },
  /** A 3px bar on the inline-start edge, e.g. the selected-row marker. */
  edge: { role: 'line', css: (v) => `box-shadow: inset 3px 0 0 0 ${v};` },
  fill: { role: 'glyph', css: (v) => `fill: ${v};` },
  stroke: { role: 'glyph', css: (v) => `stroke: ${v};` },
};

const ELEVATION: Record<'sm' | 'md' | 'lg', Array<[string, number]>> = {
  sm: [['0 1px 2px 0', 0.1]],
  md: [
    ['0 2px 6px -1px', 0.12],
    ['0 1px 2px 0', 0.08],
  ],
  lg: [
    ['0 12px 28px -6px', 0.18],
    ['0 4px 8px -2px', 0.1],
  ],
};
const DARK_ELEVATION_BOOST = 3;

function elevation(theme: Theme): string[] {
  const [r, g, b] = parseHex(shadowColor[theme]);
  const boost = theme === 'dark' ? DARK_ELEVATION_BOOST : 1;
  return Object.entries(ELEVATION).map(([size, layers]) => {
    const value = layers
      .map(
        ([geom, alpha]) => `${geom} rgb(${r} ${g} ${b} / ${Math.min(1, alpha * boost).toFixed(2)})`,
      )
      .join(', ');
    return `  --elevation-${size}: ${value};`;
  });
}

function themeBlock(theme: Theme, indent = '  '): string {
  const lines = [`${indent}color-scheme: ${theme};`];
  for (const [name, token] of Object.entries(colors))
    lines.push(`${indent}--${name}: ${token[theme]};`);
  for (const line of elevation(theme)) lines.push(indent + line.trimStart());
  return lines.join('\n');
}

export function renderTokensCss(): string {
  return `${HEADER}
/*
 * Theme resolution: light by default; dark when the OS prefers it and no
 * data-theme is set; an explicit data-theme on any element wins for that subtree.
 */
@layer theme {
:root,
[data-theme='light'] {
${themeBlock('light')}
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme='light']) {
${themeBlock('dark', '    ')}
  }
}

[data-theme='dark'] {
${themeBlock('dark')}
}
}
`;
}

export function renderColorUtilitiesCss(): string {
  const out: string[] = [HEADER];
  out.push(
    '/* Only the utilities each token role allows exist. See src/tokens/palette.ts `Role`. */\n',
  );
  for (const [name, token] of Object.entries(colors)) {
    const roles = token.roles as readonly Role[];
    for (const [prefix, { role, css }] of Object.entries(UTILITIES)) {
      if (!roles.includes(role)) continue;
      out.push(`@utility ${prefix}-${name} {\n  ${css(`var(--${name})`)}\n}\n`);
    }
  }
  return out.join('\n');
}

export interface TokenManifest {
  readonly note: string;
  readonly utilityRoles: Record<string, Role>;
  readonly tokens: Record<
    string,
    { roles: readonly Role[]; scope: 'app' | 'marketing' | 'storefront' }
  >;
}

export function renderManifest(): string {
  const manifest: TokenManifest = {
    note: 'GENERATED from src/tokens/palette.ts by scripts/build-tokens.ts. Read by @hakorem/lint-tokens. Do not edit.',
    utilityRoles: Object.fromEntries(Object.entries(UTILITIES).map(([p, u]) => [p, u.role])),
    tokens: Object.fromEntries(
      (Object.keys(colors) as ColorName[]).map((name) => {
        const t = colors[name] as {
          roles: readonly Role[];
          scope?: 'app' | 'marketing' | 'storefront';
        };
        return [name, { roles: t.roles, scope: t.scope ?? 'app' }];
      }),
    ),
  };
  return `${JSON.stringify(manifest, null, 2)}\n`;
}

export const GENERATED_FILES = {
  'src/styles/generated/tokens.css': renderTokensCss,
  'src/styles/generated/color-utilities.css': renderColorUtilitiesCss,
  'src/tokens/generated/token-manifest.json': renderManifest,
} as const;
